 * Inlined from deprecated package https://github.com/isaacs/color-support
 *
 * Detects the level of color support of the current terminal.
 */

export interface ColorSupportResult {
  level: number;
  hasBasic: boolean;
  has256: boolean;
  has16m: boolean;
}

const noColor: ColorSupportResult = { level: 0, hasBasic: false, has256: false, has16m: false };
const basic: ColorSupportResult = { level: 1, hasBasic: true, has256: false, has16m: false };
const has256: ColorSupportResult = { level: 2, hasBasic: true, has256: true, has16m: false };
const has16m: ColorSupportResult = { level: 3, hasBasic: true, has256: true, has16m: true };

export function colorSupport(stream?: { isTTY?: boolean }): ColorSupportResult {
  // No support if the stream is explicitly not a TTY.
  if (stream && stream.isTTY === false) {
    return noColor;
  }

  const env = process.env;
  const platform = process.platform;
  const term = env["TERM"] || "";

  // A "dumb" terminal has no color support unless COLORTERM overrides it.
  if (term === "dumb" && !env["COLORTERM"]) {
    return noColor;
  }

  // Generic CI environments only get color when we recognize them (Travis).
  if (env["CI"]) {
    return env["TRAVIS"] ? has256 : noColor;
  }

  if (env["TEAMCITY_VERSION"]) {
    return noColor;
  }

  // Modern Windows consoles support at least basic colors.
  if (platform === "win32") {
    return basic;
  }

  if (env["TMUX"]) {
    return has256;
  }

  switch (env["TERM_PROGRAM"]) {
    case "iTerm.app": {
      const version = env["TERM_PROGRAM_VERSION"] || "0";
      return /^[0-2]\./.test(version) ? has256 : has16m;
    }
    case "Hyper":
    case "HyperTerm":
    case "MacTerm":
      return has16m;
    case "Apple_Terminal":
      return has256;
  }

  if (/^xterm-256/.test(term)) {
    return has256;
  }

  if (/^screen|^xterm|^vt100|^linux/i.test(term)) {
    return basic;
  }

  if (env["COLORTERM"]) {
    return basic;
  }

  return noColor;
}
